  // delta(k) — целые микросекунды кадра k (spec tick, правило 1)
  function deltaUs(k) {
    clock.frame = k - 1;
    clock.advance();
    return clock.deltaUs;
  }

  function strike(s) {
    const o = obelisk.stats(s.obelisk, { timerMulti: s.stats.obeliskTimerMulti ?? 1, damageDone: s.damageDone });
