      f[t + 'Chance'] = s.stats[t + 'Chance'] ?? 0;
      f[t + 'Damage'] = s.stats[t + 'Damage'] ?? 1;
    }
    s.damageDone = obelisk.attack(f, s.rng).damageDone;
  }

  // удары боя за кадр k при нажатом пальце (правила 13–14)
  function fightFrame(s) {
    const o = obelisk.stats(s.obelisk, { timerMulti: s.stats.obeliskTimerMulti ?? 1 });
