test('бой и победа над OB1: fight → удержание → exit → victory, затем плитка меню 0 открывается', () => {
  const t0 = Date.now();
  const data = loadFight();
  const W = makeWorld1(data);
  const ob = makeObelisk(data.obelisk, data.strings.strings ?? data.strings);
  // подложено: задания 4–12 в кадре ещё не собраны — состояние сразу на задании 13; клетка урона кирки подложена (25005)
