  assert.equal(s.mode, 'omenu');
  s = W.frame(s, { touch: null, actions: [{ kind: 'victory' }] });
  assert.equal(s.obelisk, 1);
  assert.equal(s.damageDone, 0);
  assert.equal(s.mode, 'mine');
  assert.ok(s.rocks.n > 0 && s.rocks.hp.some((h) => h > 0), 'камни есть');
